package com.aicharacter.v3;
/** Converts regional impact/load into automatic guarding and load redistribution, never into dialogue or intention. */
public final class PainLocalizationEngine{private PainLocalizationEngine(){}
 public static void advance(WorldState s,double dt,long now){if(s==null||dt<=0)return;if(s.localizedPain==null)s.localizedPain=new LocalizedPainState();LocalizedPainState p=s.localizedPain;double impact=s.musculoskeletal==null?0:Math.min(1,s.musculoskeletal.impactLoad/8.0);if(impact>0){double legBias=.10*impact,chestBias=.065*impact,abdomenBias=.045*impact,neckBias=.025*impact;p.leftLeg=cl(Math.max(p.leftLeg,legBias));p.rightLeg=cl(Math.max(p.rightLeg,legBias));p.chest=cl(Math.max(p.chest,chestBias));p.abdomen=cl(Math.max(p.abdomen,abdomenBias));p.neck=cl(Math.max(p.neck,neckBias));}if(s.body!=null){double regional=p.maxLoad(),regionalPain=regional*100.0,nonspecific=s.body.hasInjury()?Math.min(18.0,4.0+s.body.injuryBurden()*14.0):0;s.body.pain=Math.max(nonspecific,Math.max(s.body.pain*.995,regionalPain));s.body.clamp();}p.syncLegacyCore();p.lastUpdatedAt=Math.max(p.lastUpdatedAt,now);}
 public static void addLandingImpact(WorldState s,double excess,double leftLoad,double rightLoad,double armLoad,double headLoad,long now){if(s.localizedPain==null)s.localizedPain=new LocalizedPainState();LocalizedPainState p=s.localizedPain;double q=Math.min(1,excess/900.0),sum=Math.max(.1,leftLoad+rightLoad);p.leftLeg=cl(p.leftLeg+q*.62*leftLoad/sum);p.rightLeg=cl(p.rightLeg+q*.62*rightLoad/sum);p.chest=cl(p.chest+q*.18);p.abdomen=cl(p.abdomen+q*.10);p.neck=cl(p.neck+q*.12*headLoad);p.leftArm=cl(p.leftArm+q*.34*armLoad);p.rightArm=cl(p.rightArm+q*.34*armLoad);p.head=cl(p.head+q*.30*headLoad);p.lastUpdatedAt=Math.max(p.lastUpdatedAt,now);}
private static double cl(double v){return Math.max(0,Math.min(1,v));}}
